#[test]
fn soft_link_cycles_fail_to_resolve() {
    let path = skip_if_missing!("soft_link_cycles.h5");
    let file = hdf5_reader::Hdf5File::open(&path).unwrap();

    // "s" -> "/s/x" leads back to "s" through the first component of its
    // own target; "a" and "b" point at each other.
    for name in ["/s", "/s/x", "/a", "/b"] {
        assert!(file.dataset(name).is_err(), "{name}");
    }
    let root = file.root_group().unwrap();
    assert!(root.group("s").is_err());

    let ok: ndarray::ArrayD<i32> = file.dataset("/ok").unwrap().read_array().unwrap();
    assert_eq!(ok.as_slice().unwrap(), &[0, 1, 2]);
    let mut names: Vec<String> = root
        .datasets()
        .unwrap()
        .iter()
        .map(|ds| ds.name().to_string())
        .collect();
    names.sort();
    assert_eq!(names, ["data", "ok"]);
}

#[test]
fn old_format_soft_links() {
    // Symbol table entries of soft links cache the link value instead of an
    // object header address.
    let path = skip_if_missing!("old_format_soft_links.h5");
    let file = hdf5_reader::Hdf5File::open(&path).unwrap();

    let link: ndarray::ArrayD<i32> = file.dataset("/link").unwrap().read_array().unwrap();
    assert_eq!(link.as_slice().unwrap(), &[0, 1, 2, 3, 4]);
    let relative: ndarray::ArrayD<i32> = file
        .dataset("/group/relative")
        .unwrap()
        .read_array()
        .unwrap();
    assert_eq!(relative.as_slice().unwrap(), &[7, 8]);
    let inner: ndarray::ArrayD<i32> = file
        .group("/group_link")
        .unwrap()
        .dataset("inner")
        .unwrap()
        .read_array()
        .unwrap();
    assert_eq!(inner.as_slice().unwrap(), &[7, 8]);

    let root = file.root_group().unwrap();
    let mut names: Vec<String> = root
        .datasets()
        .unwrap()
        .iter()
        .map(|ds| ds.name().to_string())
        .collect();
    names.sort();
    assert_eq!(names, ["data", "link"]);
    let mut groups: Vec<String> = root
        .groups()
        .unwrap()
        .iter()
        .map(|g| g.name().to_string())
        .collect();
    groups.sort();
    assert_eq!(groups, ["group", "group_link"]);

    // A dangling soft link is not listed, as in new-style groups.
    let group = file.group("/group").unwrap();
    let mut names: Vec<String> = group
        .datasets()
        .unwrap()
        .iter()
        .map(|ds| ds.name().to_string())
        .collect();
    names.sort();
    assert_eq!(names, ["inner", "relative"]);
    assert!(group.dataset("dangling").is_err());
}

#[test]
fn chunks_larger_than_the_chunk_limit_are_refused() {
    // 5x10 float32 chunks: 200 bytes each.
    let path = skip_if_missing!("simple_chunked_deflate.h5");
    let open = |max_chunk_bytes| {
        hdf5_reader::Hdf5File::open_with_options(
            &path,
            hdf5_reader::OpenOptions {
                max_chunk_bytes,
                ..Default::default()
            },
        )
        .unwrap()
    };

    let file = open(199);
    let err = file
        .dataset("/temperature")
        .unwrap()
        .read_array::<f32>()
        .unwrap_err();
    let mut source = &err;
    while let hdf5_reader::error::Error::Context { source: inner, .. } = source {
        source = inner;
    }
    assert!(
        matches!(source, hdf5_reader::error::Error::ResourceLimit(_)),
        "{err}"
    );

    let file = open(200);
    let data: ndarray::ArrayD<f32> = file.dataset("/temperature").unwrap().read_array().unwrap();
    assert_eq!(data.shape(), &[10, 20]);
}

fn is_resource_limit(err: &hdf5_reader::error::Error) -> bool {
    let mut source = err;
    while let hdf5_reader::error::Error::Context { source: inner, .. } = source {
        source = inner;
    }
    matches!(source, hdf5_reader::error::Error::ResourceLimit(_))
}

#[test]
fn sparse_huge_dataset_read_respects_limit() {
    let data = include_bytes!("../fuzz/corpus/fuzz_hdf5_open/sparse_huge_dataset.h5");
    let options = hdf5_reader::OpenOptions::default().with_max_read_bytes(256 * 1024 * 1024);
    let file = hdf5_reader::Hdf5File::from_bytes_with_options(data, options).unwrap();
    let datasets = file.root_group().unwrap().datasets().unwrap();
    assert_eq!(datasets.len(), 1);
    let err = datasets[0].read_array::<f64>().unwrap_err();
    assert!(is_resource_limit(&err), "{err}");
}

#[test]
fn reads_larger_than_the_read_limit_are_refused() {
    // 10x20 float32 in 5x10 chunks: 800 bytes, 80 bytes per row.
    let path = skip_if_missing!("simple_chunked_deflate.h5");
    let open = |max_read_bytes| {
        hdf5_reader::Hdf5File::open_with_options(
            &path,
            hdf5_reader::OpenOptions::default().with_max_read_bytes(max_read_bytes),
        )
        .unwrap()
    };
    let rows = |n| hdf5_reader::SliceInfo {
        selections: vec![
            hdf5_reader::SliceInfoElem::Slice {
                start: 0,
                end: n,
                step: 1,
            },
            hdf5_reader::SliceInfoElem::Slice {
                start: 0,
                end: 20,
                step: 1,
            },
        ],
    };

    let file = open(799);
    let ds = file.dataset("/temperature").unwrap();
    let err = ds.read_array::<f32>().unwrap_err();
    assert!(is_resource_limit(&err), "{err}");
    let err = ds.read_array_uncached::<f32>().unwrap_err();
    assert!(is_resource_limit(&err), "{err}");
    let err = ds.read_raw_bytes().unwrap_err();
    assert!(is_resource_limit(&err), "{err}");
    let err = ds.read_native_bytes().unwrap_err();
    assert!(is_resource_limit(&err), "{err}");
    let err = ds.read_slice::<f32>(&rows(10)).unwrap_err();
    assert!(is_resource_limit(&err), "{err}");
    let columns: Vec<u64> = (0..20).collect();
    let err = ds
        .read_rows_columns_chunked::<f32>((0, 10, 1), &columns)
        .unwrap_err();
    assert!(is_resource_limit(&err), "{err}");
    #[cfg(feature = "rayon")]
    {
        let err = ds.read_array_parallel::<f32>().unwrap_err();
        assert!(is_resource_limit(&err), "{err}");
        let err = ds.read_slice_parallel::<f32>(&rows(10)).unwrap_err();
        assert!(is_resource_limit(&err), "{err}");
    }

    // Smaller selections and caller-provided buffers are unaffected.
    let part = ds.read_slice::<f32>(&rows(9)).unwrap();
    assert_eq!(part.shape(), &[9, 20]);
    let part = ds
        .read_rows_columns_chunked::<f32>((0, 10, 1), &columns[..19])
        .unwrap()
        .unwrap();
    assert_eq!(part.shape(), &[10, 19]);
    let mut buffer = vec![0u8; 800];
    ds.read_raw_bytes_into(&mut buffer).unwrap();

    let file = open(800);
    let data: ndarray::ArrayD<f32> = file.dataset("/temperature").unwrap().read_array().unwrap();
    assert_eq!(data.shape(), &[10, 20]);
    assert_eq!(
        buffer,
        file.dataset("/temperature")
            .unwrap()
            .read_raw_bytes()
            .unwrap()
    );
}

#[test]
fn object_headers_larger_than_the_header_limit_are_refused() {
    let path = skip_if_missing!("simple_contiguous.h5");
    let open = |max_object_header_bytes| {
        hdf5_reader::Hdf5File::open_with_options(
            &path,
            hdf5_reader::OpenOptions::default()
                .with_max_object_header_bytes(max_object_header_bytes),
        )
        .unwrap()
    };

    // The root group's header obeys the limit too.
    let file = open(16);
    let err = match file.root_group().and_then(|root| root.members()) {
        Err(err) => err,
        Ok(_) => panic!("expected the root header to exceed the limit"),
    };
    assert!(is_resource_limit(&err), "{err}");
    let err = match file.dataset("/data") {
        Err(err) => err,
        Ok(_) => panic!("expected the dataset header to exceed the limit"),
    };
    assert!(is_resource_limit(&err), "{err}");

    let file = open(hdf5_reader::DEFAULT_MAX_OBJECT_HEADER_BYTES);
    let data: ndarray::ArrayD<f64> = file.dataset("/data").unwrap().read_array().unwrap();
    assert_eq!(data.shape(), &[4, 5]);
}

