#[test]
fn extensible_array_chunks_beyond_the_index_block() {
    // Chunks 0-3 are stored in the index block, 4-243 in data blocks it points
    // to directly, later ones behind secondary blocks; from chunk 131060 on the
    // data blocks are paged. See generate_fixtures.py for the layout.
    let path = skip_if_missing!("extensible_array_super_blocks.h5");
    let file = hdf5_reader::Hdf5File::open(&path).unwrap();

    for name in ["/data", "/data_gzip"] {
        let ds = file.dataset(name).unwrap();
        assert_eq!(ds.shape(), &[600, 4], "{name}");
        let data: ndarray::ArrayD<i32> = ds.read_array().unwrap();
        for (i, v) in data.iter().enumerate() {
            assert_eq!(*v, i as i32, "{name} element {i}");
        }

        // A selection reads only the chunks it touches.
        for (start, end) in [(30, 60), (240, 260), (495, 600)] {
            let selection = hdf5_reader::SliceInfo {
                selections: vec![
                    hdf5_reader::SliceInfoElem::Slice {
                        start,
                        end,
                        step: 1,
                    },
                    hdf5_reader::SliceInfoElem::Slice {
                        start: 0,
                        end: 4,
                        step: 1,
                    },
                ],
            };
            let slice: ndarray::ArrayD<i32> = ds.read_slice(&selection).unwrap();
            for (i, v) in slice.iter().enumerate() {
                assert_eq!(
                    *v,
                    (start * 4) as i32 + i as i32,
                    "{name} rows {start}..{end}"
                );
            }
        }
    }

    let written = [
        0, 3, 4, 19, 20, 35, 36, 51, 52, 243, 244, 499, 500, 599, 65524, 132084, 133107, 133108,
    ];
    for name in ["/sparse", "/sparse_gzip"] {
        let ds = file.dataset(name).unwrap();
        assert_eq!(ds.shape(), &[133200], "{name}");
        let data: ndarray::ArrayD<i32> = ds.read_array().unwrap();
        for (i, v) in data.iter().enumerate() {
            let expected = if written.contains(&i) { i as i32 } else { -1 };
            assert_eq!(*v, expected, "{name} element {i}");
        }

        for (start, end) in [(131050, 131070), (132080, 132090), (133100, 133200)] {
            let selection = hdf5_reader::SliceInfo {
                selections: vec![hdf5_reader::SliceInfoElem::Slice {
                    start,
                    end,
                    step: 1,
                }],
            };
            let slice: ndarray::ArrayD<i32> = ds.read_slice(&selection).unwrap();
            for (i, v) in slice.iter().enumerate() {
                let index = start as usize + i;
                let expected = if written.contains(&index) {
                    index as i32
                } else {
                    -1
                };
                assert_eq!(*v, expected, "{name} element {index}");
            }
        }
    }
}

#[test]
fn extensible_array_chunks_numbered_by_the_maximum_dimensions() {
    // Values are 0, 1, 2, ... in each dataset's shape; see generate_fixtures.py.
    let path = skip_if_missing!("extensible_array_max_dims.h5");
    let file = hdf5_reader::Hdf5File::open(&path).unwrap();
    for name in [
        "wider_max",
        "wider_max_same_chunks",
        "unlimited_last",
        "unlimited_middle",
    ] {
        let ds = file.dataset(name).unwrap();
        let shape = ds.shape().to_vec();
        let data: ndarray::ArrayD<i32> = ds.read_array().unwrap();
        for (i, v) in data.iter().enumerate() {
            assert_eq!(*v, i as i32, "{name} element {i}");
        }

        // The second half of the first dimension.
        let first = shape[0] / 2;
        let selection = hdf5_reader::SliceInfo {
            selections: shape
                .iter()
                .enumerate()
                .map(|(dim, &len)| hdf5_reader::SliceInfoElem::Slice {
                    start: if dim == 0 { first } else { 0 },
                    end: len,
                    step: 1,
                })
                .collect(),
        };
        let slice: ndarray::ArrayD<i32> = ds.read_slice(&selection).unwrap();
        let row_len: u64 = shape[1..].iter().product();
        for (i, v) in slice.iter().enumerate() {
            assert_eq!(
                *v,
                (first * row_len) as i32 + i as i32,
                "{name} slice element {i}"
            );
        }
    }
}

#[test]
fn filtered_chunk_size_fields_of_three_and_five_bytes() {
    // libhdf5 writes the chunk-size field of fixed array, extensible array and v2
    // B-tree entries 1 + (log2(chunk bytes) + 8) / 8 bytes wide: 3 bytes for the
    // 2 KiB gzip chunks, 5 bytes for the 16 MiB ones.
    let path = skip_if_missing!("filtered_chunk_size_widths.h5");
    let file = hdf5_reader::Hdf5File::open(&path).unwrap();
    for name in ["/fixed", "/extensible", "/btree_v2"] {
        let ds = file.dataset(name).unwrap();
        assert_eq!(ds.shape(), &[32, 48], "{name}");
        let data: ndarray::ArrayD<f64> = ds.read_array().unwrap_or_else(|e| panic!("{name}: {e}"));
        for (i, v) in data.iter().enumerate() {
            assert_eq!(*v, i as f64, "{name} element {i}");
        }

        let large = format!("{name}_16mib");
        let ds = file.dataset(&large).unwrap();
        assert_eq!(ds.shape(), &[4096, 2048], "{large}");
        let data: ndarray::ArrayD<f64> = ds.read_array().unwrap_or_else(|e| panic!("{large}: {e}"));
        for (i, v) in data.iter().enumerate() {
            let (r, c) = (i / 2048, i % 2048);
            let expected = if r % 1021 == 0 && c % 509 == 0 {
                i as f64
            } else {
                0.0
            };
            assert_eq!(*v, expected, "{large} element ({r}, {c})");
        }
    }
}

fn gather_expected(name: &str, row: u64, col: u64) -> f64 {
    if name == "fill" {
        return if row < 5 { 42.0 } else { -7.0 };
    }
    (row * 19 + col) as f64 - 123.0
}

#[test]
fn row_column_gathers() {
    // 17x19 datasets in 5x7 chunks; see generate_fixtures.py (20e).
    let path = skip_if_missing!("row_column_gather.h5");
    let file = hdf5_reader::Hdf5File::open(&path).unwrap();
    let columns = [18, 0, 7, 7, 13];
    let rows = (2u64, 17u64, 3u64);
    let selected_rows: Vec<u64> = (rows.0..rows.1).step_by(rows.2 as usize).collect();

    macro_rules! check {
        ($ty:ty, $name:expr) => {{
            let name: &str = $name;
            let ds = file.dataset(name).unwrap();
            let got = ds
                .read_rows_columns_chunked::<$ty>(rows, &columns)
                .unwrap()
                .expect("2-D chunked dataset");
            assert_eq!(got.shape(), &[selected_rows.len(), columns.len()], "{name}");
            for (i, &row) in selected_rows.iter().enumerate() {
                for (j, &col) in columns.iter().enumerate() {
                    assert_eq!(
                        got[[i, j]] as f64,
                        gather_expected(name, row, col),
                        "{name} ({row}, {col})"
                    );
                }
            }
            #[cfg(feature = "rayon")]
            {
                let pool = rayon::ThreadPoolBuilder::new()
                    .num_threads(4)
                    .build()
                    .unwrap();
                let cold = hdf5_reader::Hdf5File::open(&path)
                    .unwrap()
                    .dataset(name)
                    .unwrap();
                let parallel = cold
                    .read_rows_columns_chunked_in_pool::<$ty>(rows, &columns, &pool)
                    .unwrap()
                    .unwrap();
                assert_eq!(parallel, got, "{name} in pool");
                let parallel = pool
                    .install(|| ds.read_rows_columns_chunked_parallel::<$ty>(rows, &columns))
                    .unwrap()
                    .unwrap();
                assert_eq!(parallel, got, "{name} parallel");
            }

            // Out-of-range rows or columns are an error; no columns is an empty result.
            assert!(ds
                .read_rows_columns_chunked::<$ty>((0, 18, 1), &columns)
                .is_err());
            assert!(ds
                .read_rows_columns_chunked::<$ty>((0, 17, 1), &[19])
                .is_err());
            assert!(ds
                .read_rows_columns_chunked::<$ty>((0, 17, 1), &[])
                .unwrap()
                .unwrap()
                .is_empty());
        }};
    }
    for suffix in ["plain", "filtered"] {
        check!(f32, &format!("lef4{suffix}"));
        check!(f64, &format!("lef8{suffix}"));
        check!(i32, &format!("bei4{suffix}"));
    }
    check!(i32, "fill");

    // Datasets that are not 2-D and chunked are left to the caller.
    let other = skip_if_missing!("simple_contiguous.h5");
    let other = hdf5_reader::Hdf5File::open(&other).unwrap();
    assert!(other
        .dataset("/data")
        .unwrap()
        .read_rows_columns_chunked::<f64>((0, 1, 1), &[0])
        .unwrap()
        .is_none());
}

