/// Every dataset of the root group, as raw bytes, by name.
fn root_raw_bytes(file: &hdf5_reader::Hdf5File) -> Vec<(String, Vec<u8>)> {
    let mut out: Vec<_> = file
        .root_group()
        .unwrap()
        .datasets()
        .unwrap()
        .iter()
        .map(|d| (d.name().to_owned(), d.read_raw_bytes().unwrap()))
        .collect();
    out.sort();
    out
}

#[test]
fn shared_and_owned_bytes_open_without_copying_and_read_as_a_path_open() {
    use hdf5_reader::{Hdf5File, OpenOptions};
    let path = skip_if_missing!("chunked_shuffle_deflate.h5");
    let expected = root_raw_bytes(&Hdf5File::open(&path).unwrap());
    assert!(!expected.is_empty());
    let bytes = std::fs::read(&path).unwrap();

    let shared: Arc<[u8]> = bytes.clone().into();
    let file = Hdf5File::from_shared_bytes(Arc::clone(&shared)).unwrap();
    assert_eq!(root_raw_bytes(&file), expected);
    // The file reads the caller's bytes, not a copy of them.
    let view = file.storage().read_range(0, 8).unwrap();
    assert_eq!(view.as_ptr(), shared.as_ptr());
    drop((file, view));
    assert_eq!(Arc::strong_count(&shared), 1);

    let base = bytes.as_ptr();
    let file = Hdf5File::from_vec(bytes.clone()).unwrap();
    assert_eq!(root_raw_bytes(&file), expected);
    let file = Hdf5File::from_owner(bytes.into_boxed_slice(), OpenOptions::default()).unwrap();
    assert_eq!(file.storage().read_range(0, 8).unwrap().as_ptr(), base);
    assert_eq!(root_raw_bytes(&file), expected);
}

#[test]
fn reads_a_file_behind_a_user_block() {
    let path = skip_if_missing!("user_block.h5");
    let file = hdf5_reader::Hdf5File::open(&path).unwrap();
    assert_eq!(file.superblock().base_address, 1024);

    let title = file.root_group().unwrap().attribute("title").unwrap();
    assert_eq!(title.read_string().unwrap(), "behind a user block");

    let data = file.dataset("group/data").unwrap();
    let values: ndarray::ArrayD<f64> = data.read_array().unwrap();
    assert_eq!(values.shape(), &[2, 3]);
    assert_eq!(
        values.iter().copied().collect::<Vec<_>>(),
        [0., 1., 2., 3., 4., 5.]
    );

    let chunked: ndarray::ArrayD<i32> =
        file.dataset("group/chunked").unwrap().read_array().unwrap();
    assert_eq!(
        chunked.iter().copied().collect::<Vec<_>>(),
        (0..100).collect::<Vec<_>>()
    );

    let in_memory = hdf5_reader::Hdf5File::from_vec(std::fs::read(&path).unwrap()).unwrap();
    assert!(in_memory.dataset("group/data").is_ok());
}

#[test]
fn reads_v2_btrees_with_nested_internal_nodes() {
    let path = skip_if_missing!("deep_btree_v2.h5");
    let file = hdf5_reader::Hdf5File::open(&path).unwrap();
    let root = file.root_group().unwrap();

    let (_, datasets) = root.member_names().unwrap();
    assert_eq!(datasets.len(), 2001);
    for name in ["link_0000", "link_1000", "link_1999"] {
        assert!(datasets.iter().any(|member| member == name), "{name}");
        let values: ndarray::ArrayD<i32> = file.dataset(name).unwrap().read_array().unwrap();
        assert_eq!(values.iter().copied().collect::<Vec<_>>(), [0, 1, 2, 3]);
    }

    let target = file.dataset("target").unwrap();
    assert_eq!(target.attributes().len(), 2000);
    let attribute = target.attribute("attr_1999").unwrap();
    assert_eq!(attribute.read_scalar::<i32>().unwrap(), 1999);
}
